 v_type := $type0$HANDOFF_DEEP_CONTEXT$type0$;
 v_payload := $json0${"evidence_schema_version":"operational-event/v2","execution_id":"PE10_C3_BROWSER_HANDOFF_V1|COORDINATOR","producer":"PE10_C3_GPT_NATIVE_BROWSER_COORDINATOR_V1","purpose":"Prepared bounded GPT Native COORDINATOR task handoff through Claude Chrome coordinator without certifying execution.","acceptance_declared":false,"provider_attested":false,"raw_runtime_receipt":false,"subject_ref":"PROFILE_UPDATER_EVOLUTION_IMPLEMENTATION_V1/PE10_C3","evidence_tier":"USER_OWNER_APPROVED_CHAT_IN_BROWSER_UNATTESTED","task_code":"COORDINATOR","coordination_set":"PE10_C3_BROWSER_OCT2026_V1","instructions_for_gpt":"Eres Claude coordinador de PE10_C3; usa Chrome/Claude-in-Chrome si está conectado y autorizado por el usuario para operar ChatGPT GPT Native, y acceso autorizado de lectura a Supabase. NO suplantes GPT Native con una respuesta Claude, ni digas que ejecutaste algo si Chrome no está disponible. Lee ESTE evento y consulta TODOS los eventos del mismo conjunto mediante SELECT público a lf_eventos por entidad_codigo; comprueba coincidencia exacta de execution_id, SHA/ref de fuentes y accepted=false. No pegues manualmente el corpus entero ni resumas la evidencia. Trabaja en este orden: (1) lee eventos de fuentes RAW previas como evidencia del UI ORIGINAL y B R1 histórico, NO los muestres a chats productores; (2) abre chat nuevo de ChatGPT para UI_B_R2 y envía íntegro SOLO instructions_for_gpt de evento UI_B_R2; guarda RAW, URL de chat si disponible, hash y pruebas vinculadas; (3) abre chat nuevo para PRODUCT_A y envía su T1; espera JSON completo; guarda y lee luego stage_2 congelado por URL, entrégalo SOLO al mismo chat, espera y guarda; después stage_3 igual; (4) abre chat nuevo distinto para PRODUCT_B y sigue idéntica secuencia T1->T2->T3 con su candidato; NO reanudes el chat antiguo de T1 si su enlace exacto no está disponible; (5) evalúa separación de contextos y valida formato con validadores existentes; (6) después de las 7 nuevas respuestas, prepara pares anonimizado sin suprimir datos materiales, abre CHAT NUEVO separado de los productores y envía únicamente instrucciones del evento REVIEW + entradas RAW, SIN revelar mapeo A/B ni comentarios previos al evaluador; (7) recoge el dictamen RAW. Captura cada salida en evidencia inmutable mediante el transporte DB autorizado (ACT-0001 y, si aplica migración, PR->Train), en eventos adicionales como RAW_CAPTURE_BATCH_PREPARED, con run_id único, fuente, SHA256, texto RAW UTF-8 codificado en base64, chat ref, herramienta real y nivel de confianza UNATTESTED salvo fuente real. No edites eventos previos ni uses el SQL Editor para migración. Si un evento de salida no se puede registrar por vía autorizada, conserva RAW en artefactos reproducibles con hashes y reporta bloqueo; no marques una tarea completada solo por abrir el chat. No apruebes C3 ni actives v0.2 automáticamente. Entrega al final tabla tareas/salidas/id evento, resultados de validadores y limitaciones sobre atestación e independencia. El evaluador no recibe textos de las instrucciones de productor, asignación brazo ni resultados de revisión anterior.","role":"COORDINATOR","order":0,"dependencies":[],"source_case_sha":"3a365c0d027a881826e7b5566048b561fae37f74","occurred_at":"__RUNTIME_SET__"}$json0$::jsonb;
 v_payload := jsonb_set(v_payload,'{occurred_at}',to_jsonb(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"')));
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE created_by_execution_id=v_exec AND evento_tipo=v_type) THEN
