ión explícita; abrirlo no ejecuta el rechazo."       },       {         "parent_id": "reject_dialog",         "child_ids": ["reject_live_region"],         "relationship": "external_persistent_announcement_only",         "rationale": "La región de anuncio permanece montada en la página y no debe convertirse en hija DOM del modal."       }     ],     "state_map": {       "CLOSED": {         "dialog_open": false,         "request_active": false,         "focus": "reject_trigger o destino alternativo estable si el disparador desapareció.",         "announcement": "Ninguno por el simple cierre.",         "transitions": ["OPEN_IDLE"]       },       "OPEN_IDLE": {         "dialog_open": true,         "request_active": false,         "cancel": "enabled",         "confirm": "enabled",         "focus": "reject_cancel",         "announcement": "Título y explicación mediante semántica del diálogo.",         "transitions": ["CLOSED", "SUBMITTING"],         "escape": "Cancelar y cerrar sin enviar.",         "backdrop": "No ejecuta rechazo; si se habilita cierre por backdrop, usar la misma ruta de cancelación."       },       "SUBMITTING": {         "dialog_open": true,         "request_active": true,         "cancel": "disabled",         "confirm": "disabled",         "focus": "reject_status",         "announcement": "Enviando solicitud. Esperando confirmación.",         "aria_busy": true,         "escape": "PreventDefault; mantener modal abierto e informar que la solicitud está en proceso.",         "backdrop": "Sin cierre.",         "transitions": ["SUCCESS_CONFIRMED", "FAILURE_CONFIRMED", "OUTCOME_UNKNOWN"]       },       "SUCCESS_CONFIRMED": {         "dialog_open": true,         "request_active": false,         "confirmation_source": "Resultado explícito y autoritativo del servidor interpretado por el adaptador de integración.",         "cancel": "relabel_as_Cerrar",         "confirm": "hidden",         "focus": "reject_status y después control Cerrar mediante navegación normal.",         "announcement": "La oferta fue rechazada.",         "transitions": ["CLOSED"],         "post_close": "Actualizar presentación solo con estado confirmado, restaurar foco y emitir como máximo un anuncio persistente."       },       "FAILURE_CONFIRMED": {         "dialog_open": true,         "request_active": false,         "confirmation_source": "Respuesta explícita del servidor que confirma que no se aplicó el rechazo.",         "cancel": "enabled",         "confirm": "enabled_only_for_explicit_new_attempt",         "focus": "reject_status",         "announcement": "No se pudo rechazar la oferta. No se aplicó el rechazo.",         "transitions": ["OPEN_IDLE", "CLOSED"],         "postcondition": "No mostrar éxito ni actualizar la oferta como rechazada."       },       "OUTCOME_UNKNOWN": {         "dialog_open": true,         "request_active": false,         "confirmation_source": "Timeout, conexión interrumpida o error sin garantía explícita de no aplicación.",         "cancel": "relabel_as_Cerrar",         "confirm": "disabled",         "focus": "reject_status",         "announcement": "No pudimos confirmar si se rechazó la oferta. Comprueba su estado antes de intentar nuevamente.",         "transitions": ["CLOSED", "SUCCESS_CONFIRMED", "FAILURE_CONFIRMED"],         "retry": "Bloqueado hasta consultar y reconciliar un estado autoritativo del servidor.",         "postcondition": "El resultado permanece desconocido; no deducir éxito ni fracaso."       }     },     "token_map": {       "reject_dialog": {         "background": "warm_surface",         "structure": "navy_core"       },       "reject_title": {         "text": "navy_core"       },       "reject_explanation": {         "text": "slate_text"       },       "reject_cancel": {         "text_and_border": "slate_text"       },       "reject_confirm": {         "action": "green_action"       },       "reject_status": {         "informational": "slate_text",         "confirmed_result": "navy_core"       },       "focus_indicator": {         "rule": "Indicador perceptible, no dependiente únicamente del color, con contraste verificable."       },       "authority_note": "Se utilizan nombres semánticos del perfil LF; no se inventan valores hexadecimales ni equivalencias de tokens."     },     "spacing_typography": {       "modal_padding": {         "value": "16px móvil; 24px escritorio",         "mode": "EXPLORATORY_PROPOSAL",         "proposal_status": "PROPOSED_NOT_CANONICAL"       },       "control_minimum_size": {         "value": "44x44px como objetivo táctil de implementación propuesto",         "mode": "EXPLORATORY_PROPOSAL",         "proposal_status": "PROPOSED_NOT_CANONICAL"       },       "footer_gap": {         "value": "12px",         "mode": "EXPLORATORY_PROPOSAL",         "proposal_status": "PROPOSED_NOT_CANONICAL"       },       "font": "Respetar familia tipográfica existente de LF; no sustituirla.",       "zoom": "Permitir ampliación del texto y zoom sin pérdida de controles.",       "responsive_rule": "Priorizar visibilidad, reflujo y operación por encima de tamaños fijos."     },     "density_rules": [       {         "rule": "Mantener únicamente dos decisiones iniciales: Cancelar y Confirmar rechazo."       },       {         "rule": "Durante SUBMITTING no presentar una acción adicional de rechazo ni una cancelación engañosa."       },       {         "rule": "Mostrar un solo mensaje de estado autoritativo, evitando banners, toasts y diálogos redundantes."       },       {         "rule": "No introducir contadores, ofertas alternativas, urgencia ni elementos promocionales."       }     ],     "remediation_actions": [       {         "issue_id": "R206-01",         "priority": "P0",         "category": "INTERACTION",         "evidence_component_ids": ["reject_dialog", "reject_cancel", "reject_trigger", "reject_confirm"],         "evidence_anchor": "open=true; document.querySelector('#confirm').focus() y ausencia de restauración de foco.",         "decision": "Cambiar el estado inicial del foco a reject_cancel y devolverlo al disparador al cerrar.",         "implementation_change": "En reject_dialog reemplazar la apertura manual por dialog.showModal(). Guardar document.activeElement antes de abrir. Tras montar el contenido, enfocar reject_cancel y no reject_confirm. Utilizar el comportamiento modal nativo de Tab y Shift+Tab, impedir desplazamiento de foco al fondo y restaurar al cerrar el elemento original si permanece conectado. Si desapareció, enfocar un elemento estable de contexto con tabindex=-1. Con Escape ejecutar cierre sin efecto únicamente antes del envío.",         "acceptance_criteria": "Orden observable: reject_trigger -> reject_cancel -> reject_confirm mediante Tab -> reject_cancel mediante Shift+Tab -> reject_trigger después de Escape o Cancelar. No se produce solicitud de rechazo.",         "execution": {           "operation": "SET_STATE",           "target_component_id": "reject_dialog",           "property": "initial_focus_and_restoration",           "desired_value": "initial=reject_cancel; trapped=true; restore=original_trigger_or_stable_fallback"         },         "acceptance_check": {           "check_type": "STATE",           "target_component_id": "reject_dialog",           "expected": "Foco inicial neutral, navegación contenida y restauración verificable."         },         "semantic_authority": {           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "authority_type": "RAW_INPUT",           "claim_boundary": "El pedido exige rechazo voluntario y soporte de teclado y lector de pantalla; no autoriza confirmación automática."         },         "precision_basis": {           "mode": "RELATIVE_GUIDANCE",           "source_refs": [],           "value_or_rule": "Foco al primer control neutral, restauración a origen o contexto estable.",           "proposal_status": "PROPOSED_NOT_CANONICAL"         }       },       {         "issue_id": "R206-02",         "priority": "P0",         "category": "INTERACTION",         "evidence_component_ids": ["reject_confirm", "reject_dialog", "reject_status"],         "evidence_anchor": "Pulsaciones rápidas sobre Confirmar rechazo generan riesgo de doble envío.",         "decision": "Establecer bloqueo sincrónico de reject_confirm y una sola transición a SUBMITTING.",         "implementation_change": "Utilizar un único controlador para click, Enter y Space, conservando el click nativo del botón. Antes de cualquier await comprobar phase==='OPEN_IDLE' e inFlight===false; asignar inFlight=true sincrónicamente; pasar a SUBMITTING; deshabilitar reject_confirm y reject_cancel; mover el foco a reject_status. No asociar además un keydown que vuelva a invocar el envío. Liberar inFlight al resolver la operación, conservando bloqueado el reintento cuando el resultado sea desconocido.",         "acceptance_criteria": "Una ráfaga de 10 activaciones rápidas produce exactamente una invocación al adaptador de envío en la instancia de UI, mientras el estado permanece SUBMITTING.",         "execution": {           "operation": "SET_STATE",           "target_component_id": "reject_confirm",           "property": "atomic_submission_guard",           "desired_value": "enabled_only_when_OPEN_IDLE_and_not_inFlight"         },         "acceptance_check": {           "check_type": "STATE",           "target_component_id": "reject_confirm",           "expected": "Una invocación por intento y control deshabilitado desde el primer evento."         },         "semantic_authority": {           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "authority_type": "RAW_INPUT",           "claim_boundary": "La protección local evita activaciones duplicadas en esa instancia; no demuestra idempotencia entre pestañas o clientes."         },         "precision_basis": {           "mode": "UPSTREAM_VALUE",           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "value_or_rule": "enabled_only_when_OPEN_IDLE_and_not_inFlight",           "proposal_status": "NOT_APPLICABLE"         }       },       {         "issue_id": "R206-03",         "priority": "P0",         "category": "COPY",         "evidence_component_ids": ["reject_live_region", "reject_status", "reject_dialog"],         "evidence_anchor": "El cierre del diálogo dispara Rechazo exitoso antes de recibir confirmación del servidor.",         "decision": "Reemplazar el anuncio prematuro de reject_live_region por un resultado condicionado al servidor.",         "implementation_change": "Eliminar la publicación de Rechazo exitoso desde eventos close, unmount o finally. reject_status anunciará procesamiento mientras esté pendiente. reject_live_region solo anunciará éxito después de obtener una confirmación autoritativa del servidor, o comunicará incertidumbre si no existe. No interpretar HTTP 200, resolución de promesa o cierre como prueba suficiente sin validar el contenido de negocio.",         "acceptance_criteria": "Cerrar por Cancelar o Escape no anuncia rechazo exitoso. Durante SUBMITTING tampoco aparece. Solo una confirmación explícita del servidor habilita el mensaje de éxito.",         "execution": {           "operation": "REPLACE_COPY",           "target_component_id": "reject_live_region",           "property": "announcement_source",           "desired_value": "server_confirmed_result_only"         },         "acceptance_check": {           "check_type": "COPY_EQUALS",           "target_component_id": "reject_live_region",           "expected": "En éxito confirmado: La oferta fue rechazada. En cancelación: ningún anuncio de resultado."         },         "semantic_authority": {           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "authority_type": "RAW_INPUT",           "claim_boundary": "La única fuente de resultado es el servidor; no se infieren efectos jurídicos ni cierre de deuda."         }       },       {         "issue_id": "R206-04",         "priority": "P0",         "category": "INTERACTION",         "evidence_component_ids": ["reject_status", "reject_dialog", "reject_cancel"],         "evidence_anchor": "La interfaz existente no discrimina resultado confirmado, fallo de servidor ni timeout.",         "decision": "Establecer en reject_status estados mutuamente excluyentes de éxito, fallo confirmado y resultado desconocido.",         "implementation_change": "Usar un adaptador que traduzca la respuesta real del servidor a CONFIRMED_REJECTED, CONFIRMED_NOT_APPLIED o UNKNOWN. Mostrar éxito solo con CONFIRMED_REJECTED. Mostrar fallo sin aplicación solo con CONFIRMED_NOT_APPLIED. Ante timeout, desconexión o respuesta ambigua pasar a OUTCOME_UNKNOWN; bloquear reintento y permitir únicamente cierre informativo o consulta del estado autoritativo si existe integración de lectura. El timeout local no debe tratarse como cancelación de la operación del servidor.",         "acceptance_criteria": "Cada resultado tiene una única representación. Un error ambiguo o timeout nunca origina un mensaje de éxito, confirmación de no aplicación ni reenvío automático.",         "execution": {           "operation": "SET_STATE",           "target_component_id": "reject_status",           "property": "server_outcome_state_machine",           "desired_value": "CONFIRMED_REJECTED|CONFIRMED_NOT_APPLIED|UNKNOWN"         },         "acceptance_check": {           "check_type": "STATE",           "target_component_id": "reject_status",           "expected": "Mapeo exclusivo de estados basado en evidencia autoritativa y comportamiento conservador ante incertidumbre."         },         "semantic_authority": {           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "authority_type": "RAW_INPUT",           "claim_boundary": "El pedido exige resultado desde servidor, fallo y timeout; los tres nombres del adaptador son un contrato local propuesto, no estados verificados de un servicio existente."         },         "precision_basis": {           "mode": "EXPLORATORY_PROPOSAL",           "source_refs": [],           "value_or_rule": "Máquina de seis estados UI con clasificación explícita de respuesta autoritativa.",           "proposal_status": "PROPOSED_NOT_CANONICAL"         }       },       {         "issue_id": "R206-05",         "priority": "P1",         "category": "LAYOUT",         "evidence_component_ids": ["reject_cancel", "reject_dialog", "reject_confirm"],         "evidence_anchor": "El teclado virtual móvil ocupa parte del viewport y oculta Cancelar.",         "decision": "Mover reject_cancel a un footer persistente dentro de la altura visual disponible.",         "implementation_change": "En reject_dialog utilizar layout flex-column con cuerpo desplazable y footer no reducible. Ubicar reject_cancel antes de reject_confirm en orden DOM y visual. Ajustar el alto máximo del modal a visualViewport.height cuando la API exista, considerar visualViewport.offsetTop y safe-area-inset-bottom, y recalcular al abrir teclado, redimensionar o desplazar viewport. Utilizar CSS 100dvh como respaldo y comprobar que ningún control permanezca cubierto.",         "acceptance_criteria": "Con teclado virtual abierto, zoom o viewport pequeño, reject_cancel permanece visible, recibe foco y puede activarse sin cerrar el teclado como requisito previo.",         "execution": {           "operation": "MOVE",           "target_component_id": "reject_cancel",           "property": "responsive_footer_placement",           "desired_value": "visible_footer_within_visual_viewport"         },         "acceptance_check": {           "check_type": "RELATIONSHIP",           "target_component_id": "reject_cancel",           "expected": "El rectángulo de reject_cancel queda dentro del viewport visual disponible y no está ocluido."         },         "precision_basis": {           "mode": "RELATIVE_GUIDANCE",           "source_refs": [],           "value_or_rule": "Mantener el footer dentro del viewport visual, respetando área segura y contenido desplazable.",           "proposal_status": "PROPOSED_NOT_CANONICAL"         }       },       {         "issue_id": "R206-06",         "priority": "P0",         "category": "INTERACTION",         "evidence_component_ids": ["reject_cancel", "reject_dialog", "reject_status"],         "evidence_anchor": "Cancelar carece de una semántica segura cuando la solicitud ya está pendiente.",         "decision": "Definir reject_cancel como cancelación sin efecto únicamente antes del envío.",         "implementation_change": "En OPEN_IDLE, reject_cancel cierra el diálogo sin llamar al adaptador de envío. En SUBMITTING, deshabilitar Cancelar, impedir Escape y backdrop, y explicar que la solicitud está en curso. En SUCCESS_CONFIRMED y OUTCOME_UNKNOWN reemplazar su etiqueta por Cerrar, sin prometer deshacer una solicitud. En FAILURE_CONFIRMED permitir Cancelar solo cuando el servidor haya confirmado que no aplicó el rechazo.",         "acceptance_criteria": "Cancelar desde OPEN_IDLE produce cero solicitudes. Después de iniciar envío, ningún cierre se presenta como anulación de una operación que podría haberse procesado.",         "execution": {           "operation": "SET_STATE",           "target_component_id": "reject_cancel",           "property": "cancellation_semantics",           "desired_value": "cancel_before_send_only; disabled_during_send; close_after_result"         },         "acceptance_check": {           "check_type": "STATE",           "target_component_id": "reject_cancel",           "expected": "Cancelación sin efecto antes del envío y cierre informativo cuando ya existe un resultado o incertidumbre."         },         "semantic_authority": {           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "authority_type": "RAW_INPUT",           "claim_boundary": "El negocio exige cancelación sin efecto; no existe evidencia de que el cliente pueda revertir una solicitud ya enviada."         },         "precision_basis": {           "mode": "UPSTREAM_VALUE",           "source_refs": ["RAW_INPUT:PESC3-V2-206"],           "value_or_rule": "cancel_before_send_only; disabled_during_send; close_after_result",           "proposal_status": "NOT_APPLICABLE"         }       }     ],     "risk_controls": [       {         "id": "RC01",         "risk": "Una solicitud puede haberse aplicado pese a timeout o cierre de conexión.",         "control": "Clasificar como OUTCOME_UNKNOWN y consultar estado autoritativo antes de permitir reintento.",         "residual_risk": "Sin consulta de estado o idempotencia garantizada por servidor, no puede asegurarse ausencia de duplicación después de una interrupción."       },       {         "id": "RC02",         "risk": "Doble envío desde pestañas diferentes, clientes distintos o reintentos de red.",         "control": "Exigir verificación del contrato real de idempotencia o deduplicación del backend antes de afirmar protección extremo a extremo.",         "residual_risk": "El bloqueo sincrónico del botón solo cubre la instancia local."       },       {         "id": "RC03",         "risk": "Una respuesta técnica exitosa podría no representar rechazo confirmado.",         "control": "Usar adaptador de interpretación del resultado de negocio, sin asumir nombres de endpoints o campos inexistentes.",         "residual_risk": "El mapping real queda condicionado a verificar el contrato de integración."       },       {         "id": "RC04",         "risk": "Un cierre o desmontaje prematuro puede ocultar mensajes al lector de pantalla.",         "control": "Mantener resultado visible en el modal hasta cierre explícito; conservar región de anuncios fuera del modal y devolver el foco.",         "residual_risk": "El comportamiento exacto requiere prueba con lectores de pantalla y navegadores objetivo."       },       {         "id": "RC05",         "risk": "Un teclado virtual o zoom puede ocultar los controles.",         "control": "Ajustar altura al viewport visual, mantener footer accesible y verificar visibilidad geométrica y táctil.",         "residual_risk": "La implementación de visualViewport y el desplazamiento del teclado varían entre navegadores."       },       {         "id": "RC06",         "risk": "La interfaz puede inducir presión o comunicar efectos no autorizados.",         "control": "Conservar Cancelar como primera opción de foco, evitar urgencia, mensajes de culpa, garantías y afirmaciones contractuales no suministradas.",         "residual_risk": "No se atribuyen consecuencias legales al rechazo."       },       {         "id": "RC07",         "risk": "El disparador podría desaparecer después de una operación confirmada.",         "control": "Restaurar foco al disparador si existe o a un elemento estable de contexto que represente el estado actualizado.",         "residual_risk": "El destino concreto debe verificarse en la pantalla real."       }     ],     "prompt_constraints": [       "Conservar el diálogo existente; no crear una pantalla nueva.",       "No enfocar Confirmar rechazo automáticamente.",       "Utilizar diálogo modal semántico con etiquetas accesibles y navegación de teclado.",       "Mantener cancelación sin efecto antes de iniciar la operación.",       "No informar éxito por cierre, HTTP 200 genérico ni resolución local de una promesa.",       "Bloquear doble activación local de forma sincrónica.",       "No reintentar automáticamente después de timeout o respuesta ambigua.",       "Preservar controles dentro del viewport visual con teclado móvil.",       "No inventar endpoint, servicio, estado real de backend, efecto legal ni token visual canónico.",       "No modificar Shell o componentes fuera de alcance.",       "Tratar las pruebas observacionales definidas como no ejecutadas hasta contar con resultados reales."     ]   },   "score": {     "layout_precision": 4,     "visual_hierarchy": 4,     "lf_system_fidelity": 4,     "state_mapping": 5,     "handoff_quality": 4,     "total": 21,     "evidence_by_criterion": {       "layout_precision": {         "refs": ["layout_grid", "spacing_typography", "reject_cancel"],         "summary": "La especificación define comportamiento de escritorio y móvil, footer persistente, viewport visual y dimensiones explícitamente propuestas."       },       "visual_hierarchy": {         "refs": ["visual_hierarchy", "reject_title", "reject_cancel"],         "summary": "El orden visual y de foco favorece la comprensión y una salida voluntaria antes de confirmar el rechazo."       },       "lf_system_fidelity": {         "refs": ["token_map", "risk_controls"],         "summary": "La propuesta utiliza tokens semánticos LF sin inventar valores canónicos y evita patrones coercitivos o afirmaciones financieras no respaldadas."       },       "state_mapping": {         "refs": ["state_map", "reject_status", "reject_confirm"],         "summary": "Se diferencian cierre, apertura, envío, éxito confirmado, fallo confirmado e incertidumbre, incluyendo reglas de foco y transición."       },       "handoff_quality": {         "refs": ["remediation_actions", "handoff_to_next"],         "summary": "Las acciones tienen operación, objetivo y aceptación observable; falta conectar y ejecutar la verificación sobre una implementación real."       }     }   },   "handoff_to_next": {     "destination": "QUALITY_PACK",     "handoff_status": "SPECIFICATION_READY_FOR_VALIDATION_NOT_CERTIFIED",     "implementation_blueprint": {       "technology": "DOM y HTMLDialogElement; trasladable al framework existente sin asumir cuál utiliza.",       "markup": [         "\<button id=\\"reject-trigger\\" type=\\"button\\">Rechazar oferta\</button>",         "\<dialog id=\\"reject-dialog\\" aria-labelledby=\\"reject-title\\" aria-describedby=\\"reject-description\\">",         "  \<h2 id=\\"reject-title\\">¿Rechazar esta oferta?\</h2>",         "  \<p id=\\"reject-description\\">Puedes cancelar sin enviar ninguna solicitud. Si confirmas, esperaremos la respuesta del servidor.\</p>",         "  \<div id=\\"reject-status\\" role=\\"status\\" aria-live=\\"polite\\" aria-atomic=\\"true\\" tabindex=\\"-1\\">\</div>",         "  \<div class=\\"reject-footer\\">",         "    \<button id=\\"reject-cancel\\" type=\\"button\\" autofocus>Cancelar\</button>",         "    \<button id=\\"reject-confirm\\" type=\\"button\\">Confirmar rechazo\</button>",         "  \</div>",         "\</dialog>",         "\<div id=\\"reject-live-region\\" role=\\"status\\" aria-live=\\"polite\\" aria-atomic=\\"true\\">\</div>"       ],       "controller_pseudocode": [         "const phase = { value: 'CLOSED' }; let inFlight = false; let opener = null;",         "const dialog = document.getElementById('reject-dialog'); const cancel = document.getElementById('reject-cancel'); const confirm = document.getElementById('reject-confirm'); const status = document.getElementById('reject-status');",         "function openDialog() { if (phase.value !== 'CLOSED') return; opener = document.activeElement; phase.value = 'OPEN_IDLE'; render(); dialog.showModal(); queueMicrotask(() => cancel.focus()); }",         "function closeDialog() { if (phase.value === 'SUBMITTING') return; const previous = phase.value; dialog.close(); phase.value = 'CLOSED'; render(); queueMicrotask(() => { const target = opener?.isConnected ? opener : getStableContextTarget(); target?.focus(); announceConfirmedResultAfterClose(previous); }); }",         "cancel.addEventListener('click', () => { if (phase.value === 'OPEN_IDLE' || phase.value === 'FAILURE_CONFIRMED' || phase.value === 'SUCCESS_CONFIRMED' || phase.value === 'OUTCOME_UNKNOWN') closeDialog(); });",         "dialog.addEventListener('cancel', event => { event.preventDefault(); if (phase.value !== 'SUBMITTING') closeDialog(); else status.textContent = 'La solicitud sigue en proceso.'; });",         "confirm.addEventListener('click', submitOnce);",         "async function submitOnce() { if (phase.value !== 'OPEN_IDLE' || inFlight) return; inFlight = true; phase.value = 'SUBMITTING'; render(); status.focus(); try { const response = await submitRejectionThroughVerifiedAdapter(); const result = classifyAuthoritativeServerResponse(response); if (result === 'CONFIRMED_REJECTED') phase.value = 'SUCCESS_CONFIRMED'; else if (result === 'CONFIRMED_NOT_APPLIED') phase.value = 'FAILURE_CONFIRMED'; else phase.value = 'OUTCOME_UNKNOWN'; } catch (error) { phase.value = 'OUTCOME_UNKNOWN'; } finally { inFlight = false; render(); status.focus(); } }",         "function render() { const pending = phase.value === 'SUBMITTING'; confirm.disabled = phase.value !== 'OPEN_IDLE'; cancel.disabled = pending; dialog.setAttribute('aria-busy', String(pending)); cancel.textContent = ['SUCCESS_CONFIRMED', 'OUTCOME_UNKNOWN'].includes(phase.value) ? 'Cerrar' : 'Cancelar'; status.textContent = stateMessage(phase.value); }",         "function stateMessage(s) { return ({ SUBMITTING: 'Enviando solicitud. Esperando confirmación.', SUCCESS_CONFIRMED: 'La oferta fue rechazada.', FAILURE_CONFIRMED: 'No se pudo rechazar la oferta. El servidor confirmó que no se aplicó.', OUTCOME_UNKNOWN: 'No pudimos confirmar si se rechazó la oferta. Comprueba su estado antes de intentar nuevamente.' })[s] || ''; }",         "El controlador debe implementar el estado de reintento explícito desde FAILURE_CONFIRMED antes de habilitar una nueva invocación. Nunca llamar submitOnce desde OUTCOME_UNKNOWN.",         "submitRejectionThroughVerifiedAdapter, classifyAuthoritativeServerResponse, getStableContextTarget y announceConfirmedResultAfterClose son puntos de integración: deben conectarse al contrato existente. Ninguna de estas funciones representa un endpoint verificado.",         "Registrar cierre solo mediante closeDialog o una ruta equivalente centralizada; no dejar cierres implícitos mediante formularios dialog o handlers duplicados.",         "Registrar los escuchadores del viewport visual con limpieza al desmontar; evitar referencias DOM obsoletas y múltiples listeners durante reaperturas."       ],       "responsive_css": [         "#reject-dialog {